### 2. API Client

```typescript
// api/userPreferencesClient.ts

import {
  UserPreferences,
  UserPreferencesResponse,
  ApiErrorResponse,
  ApiError,
} from '../types/userPreferences';

/**
 * Configuration for API client
 */
export interface ApiClientConfig {
  baseUrl?: string;
  timeout?: number;
}

/**
 * Default configuration
 */
const DEFAULT_CONFIG: Required<ApiClientConfig> = {
  baseUrl: '/api',
  timeout: 10000, // 10 seconds
};

/**
 * User Preferences API Client
 */
export class UserPreferencesClient {
  private config: Required<ApiClientConfig>;

  constructor(config: ApiClientConfig = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Retrieve authentication token from storage
   * Override this method to customize token retrieval
   */
  protected getAuthToken(): string | null {
    // Default implementation - reads from localStorage
    // In production, use secure token storage
    return localStorage.getItem('auth_token');
  }

  /**
   * Fetch user preferences
   * 
   * @throws {ApiError} When request fails or returns error
   * @returns {Promise<UserPreferences>} User preferences data
   */
  async getUserPreferences(): Promise<UserPreferences> {
    const token = this.getAuthToken();

    if (!token) {
      throw new ApiError('Authentication token not found', 401);
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeout);

    try {
      const response = await fetch(
        `${this.config.baseUrl}/user/preferences`,
        {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
          signal: controller.signal,
        }
      );

      clearTimeout(timeoutId);

      // Handle HTTP error responses
      if (!response.ok) {
        const errorData: ApiErrorResponse = await response
          .json()
          .catch(() => ({ error: 'Unknown error occurred' }));

        throw new ApiError(
          errorData.error || `HTTP ${response.status} error`,
          response.status,
          errorData
        );
      }

      // Parse successful response
      const data: UserPreferencesResponse = await response.json();

      if (!data.success || !data.data) {
        throw new ApiError('Invalid response format', 500);
      }

      return data.data;

    } catch (error) {
      clearTimeout(timeoutId);

      // Handle network errors
      if (error instanceof TypeError || error.name === 'AbortError') {
        throw new ApiError(
          'Network request failed. Please check your connection.',
          0
        );
      }

      // Re-throw ApiError instances
      if (error instanceof ApiError) {
        throw error;
      }

      // Handle unknown errors
      throw new ApiError(
        'An unexpected error occurred',
        500
      );
    }
  }
}

/**
 * Default singleton instance
 */
export const userPreferencesClient = new UserPreferencesClient();

/**
 * Convenience function for fetching user preferences
 */
export const getUserPreferences = (): Promise<UserPreferences> => {
  return userPreferencesClient.getUserPreferences();
};
```

### 3. React Hook with State Management (Usage Example)

```typescript
// hooks/useUserPreferences.ts

import { useState, useEffect, useCallback } from 'react';
import {
  UserPreferences,
  LoadingState,
  ApiError,
} from '../types/userPreferences';
import { getUserPreferences } from '../api/userPreferencesClient';

/**
 * Hook return type
 */
export interface UseUserPreferencesReturn {
  preferences: UserPreferences | null;
  loading: LoadingState;
  error: string | null;
  refetch: () => Promise<void>;
}

/**
 * React hook for fetching and managing user preferences
 * 
 * @param autoFetch - Whether to fetch preferences on mount (default: true)
 * @returns {UseUserPreferencesReturn} Preferences data, loading state, and refetch function
 */
export const useUserPreferences = (
  autoFetch: boolean = true
): UseUserPreferencesReturn => {
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState<LoadingState>('idle');
  const [error, setError] = useState<string | null>(null);

  const fetchPreferences = useCallback(async () => {
    setLoading('loading');
    setError(null);

    try {
      const data = await getUserPreferences();
      setPreferences(data);
      setLoading('success');
    } catch (err) {
      const errorMessage = err instanceof ApiError
        ? err.message
        : 'Failed to fetch preferences';

      setError(errorMessage);
      setLoading('error');
      console.error('Error fetching user preferences:', err);
    }
  }, []);

  useEffect(() => {
    if (autoFetch) {
      fetchPreferences();
    }
  }, [autoFetch, fetchPreferences]);

  return {
    preferences,
    loading,
    error,
    refetch: fetchPreferences,
  };
};
