global.fetch = jest.fn();

describe('UserPreferencesClient', () => {
  let client: UserPreferencesClient;

  beforeEach(() => {
    client = new UserPreferencesClient({ baseUrl: '/api' });
    jest.clearAllMocks();

    // Mock localStorage
    Storage.prototype.getItem = jest.fn(() => 'mock-token-123');
  });

  it('should fetch user preferences successfully', async () => {
    const mockResponse = {
      ok: true,
      status: 200,
      json: async () => ({ success: true, data: mockUserPreferences }),
    };

    (fetch as jest.Mock).mockResolvedValueOnce(mockResponse);

    const result = await client.getUserPreferences();

    expect(fetch).toHaveBeenCalledWith(
      '/api/user/preferences',
      expect.objectContaining({
        method: 'GET',
        headers: expect.objectContaining({
          'Authorization': 'Bearer mock-token-123',
        }),
      })
