// components/UserPreferencesDisplay.tsx

import React from 'react';
import { useUserPreferences } from '../hooks/useUserPreferences';

/**
 * Example component displaying user preferences
 */
export const UserPreferencesDisplay: React.FC = () => {
  const { preferences, loading, error, refetch } = useUserPreferences();

  if (loading === 'loading') {
    return <div>Loading preferences...</div>;
  }

  if (error) {
    return (
      <div>
        <p>Error: {error}</p>
        <button onClick={refetch}>Retry</button>
      </div>
    );
  }

  if (!preferences) {
    return <div>No preferences available</div>;
  }

  return (
    <div>
      <h2>User Preferences</h2>
      <dl>
        <dt>Theme:</dt>
        <dd>{preferences.theme}</dd>

        <dt>Language:</dt>
        <dd>{preferences.language}</dd>

        <dt>Timezone:</dt>
        <dd>{preferences.timezone}</dd>

        <dt>Email Notifications:</dt>
        <dd>{preferences.notifications.email ? 'Enabled' : 'Disabled'}</dd>

        <dt>Push Notifications:</dt>
        <dd>{preferences.notifications.push ? 'Enabled' : 'Disabled'}</dd>

        <dt>SMS Notifications:</dt>
        <dd>{preferences.notifications.sms ? 'Enabled' : 'Disabled'}</dd>
      </dl>

